import {Component,Input} from '@angular/core';import {CommonModule} from '@angular/common';import {Router} from '@angular/router';import {ReservationAuthService} from '../services/reservation-auth.service';import {LanguageService} from '../services/language.service';import {inquiryFromForm,inquiryQuery} from './booking-inquiry';import {prebookingText} from './prebooking-text';
@Component({selector:'app-booking-question',standalone:true,imports:[CommonModule],template:`<button type="button" (click)="ask()" [disabled]="disabled||busy">{{t(0)}}</button><p *ngIf="error" role="alert">{{error}}</p>`,styles:[`:host{display:inline-block}button{border:1px solid #14556a;color:#14556a;background:white;border-radius:9px;padding:12px 16px;font:600 15px/1.4 sans-serif;cursor:pointer}button:disabled{opacity:.5;cursor:default}button:focus-visible{outline:3px solid #f88b20;outline-offset:3px}p{color:#a52924;max-width:400px;font-size:14px}`]})
export class BookingQuestionComponent {
 @Input()type='';@Input()assetId='';@Input()form:any={};@Input()disabled=false;busy=false;error='';constructor(private auth:ReservationAuthService,private router:Router,public language:LanguageService){}t(i:number){return prebookingText(this.language.currentLanguage,i);}
 async ask(){if(this.busy)return;this.error='';let query:any;try{query=inquiryQuery(this.type,this.assetId,inquiryFromForm(this.type,this.form));}catch{this.error=this.t(6);return;}this.busy=true;try{await this.auth.user();await this.router.navigate(['/messages'],{queryParams:query});}catch{const returnUrl=this.router.serializeUrl(this.router.createUrlTree(['/messages'],{queryParams:query}));await this.router.navigate(['/account/login'],{queryParams:{role:'customer',returnUrl}});}finally{this.busy=false;}}
}
